import re


_JOB_RE = re.compile(
    r"^JOB (?P<name>\S+) AT (?P<at>\d{2}:\d{2}) "
    r"RUN (?P<script>\S+\.crms)"
    r"(?: ON_ERROR (?P<error>ABORT|CONTINUE|RETRY:(?P<retries>\d+)))?$"
)


def parse_schedule(cfg_text: str) -> list[dict]:
    """Parse a Meridian CRM batch schedule without performing I/O."""
    jobs: list[dict] = []

    for line_number, raw_line in enumerate(cfg_text.splitlines(), start=1):
        line = raw_line.strip()
        if not line or line.startswith("#"):
            continue

        match = _JOB_RE.fullmatch(line)
        if match is None:
            raise ValueError(f"invalid schedule line {line_number}: {raw_line!r}")

        hour, minute = (int(part) for part in match.group("at").split(":"))
        if hour > 23 or minute > 59:
            raise ValueError(f"invalid time on line {line_number}: {match.group('at')!r}")

        error_clause = match.group("error")
        if error_clause is None or error_clause == "ABORT":
            policy = "ABORT"
            retries = 0
        elif error_clause == "CONTINUE":
            policy = "CONTINUE"
            retries = 0
        else:
            policy = "RETRY"
            retries = int(match.group("retries"))

        jobs.append(
            {
                "name": match.group("name"),
                "at": match.group("at"),
                "script": match.group("script"),
                "on_error": {"policy": policy, "retries": retries},
            }
        )

    return jobs
